import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { join } from "node:path";
import { TokenDb } from "./db.js";
import { type RangeOption, type BreakdownOption, nextRange, nextBreakdown, getBreakdownsForRange, rangeStartDate, rangeLabel, renderHeader, renderTable, renderFooter } from "./render.js";
import type { Breakdown } from "./db.js";
import { matchesKey, Key } from "@mariozechner/pi-tui";

const DB_PATH = join(process.env.HOME ?? "~", ".pi", "agent", "data", "token-usage.db");

export default function (pi: ExtensionAPI) {
  const db = new TokenDb(DB_PATH);

  // --- Main agent loop: track assistant messages ---
  pi.on("message_end", async (event, _ctx) => {
    const msg = event.message;
    if (msg.role !== "assistant") return;

    const usage = msg.usage;
    db.insert({
      provider: msg.provider ?? "unknown",
      model: msg.model ?? "unknown",
      input: usage.input ?? 0,
      output: usage.output ?? 0,
      cacheRead: usage.cacheRead ?? 0,
      cacheWrite: usage.cacheWrite ?? 0,
      source: "agent",
      cwd: _ctx.cwd ?? null,
    });
  });

  // --- Extension out-of-band calls ---
  pi.events.on("model:usage", ((data: {
    provider: string;
    model: string;
    input: number;
    output: number;
    cacheRead?: number;
    cacheWrite?: number;
  }) => {
    db.insert({
      provider: data.provider,
      model: data.model,
      input: data.input,
      output: data.output,
      cacheRead: data.cacheRead ?? 0,
      cacheWrite: data.cacheWrite ?? 0,
      source: "extension",
      cwd: process.cwd(),
    });
  }) as (data: unknown) => void);

  // --- Cleanup ---
  pi.on("session_shutdown", () => {
    db.close();
  });

  // --- /token-usage command ---
  pi.registerCommand("token-usage", {
    description: "Show token usage breakdown by model with configurable time ranges",
    handler: async (_args, ctx) => {
      if (!ctx.hasUI) {
        ctx.ui.notify("Token usage requires interactive mode", "warning");
        return;
      }

      let range: RangeOption = "week";
      let breakdown: BreakdownOption = getBreakdownsForRange(range)[0];

      await ctx.ui.custom<void>((tui, theme, _kb, done) => {
        const renderView = (): string[] => {
          const lines: string[] = [];

          const startDate = rangeStartDate(range);
          const now = new Date();
          const rows = db.queryGrouped(startDate, now, breakdown as Breakdown, undefined);
          const totals = db.totals(startDate, now);

          lines.push(renderHeader(theme, startDate, range));
          lines.push(...renderTable(
            rows.map(r => ({ ...r })),
            totals,
            breakdown as Breakdown,
            theme,
            process.stdout.columns ?? 80,
          ));
          lines.push("");
          lines.push(renderFooter(theme, range, breakdown, getBreakdownsForRange(range).length > 1));

          return lines;
        };

        let cachedLines: string[] = renderView();

        return {
          render(_width: number): string[] {
            return cachedLines;
          },
          invalidate(): void {
            cachedLines = renderView();
          },
          handleInput(data: string): void {
            if (matchesKey(data, "escape") || data === "q") {
              done();
            } else if (matchesKey(data, Key.ctrl("r"))) {
              range = nextRange(range);
              breakdown = getBreakdownsForRange(range)[0];
              cachedLines = renderView();
              tui.requestRender();
            } else if (matchesKey(data, Key.tab)) {
              breakdown = nextBreakdown(range, breakdown);
              cachedLines = renderView();
              tui.requestRender();
            }
          },
        };
      });
    },
  });
}

import Database from "better-sqlite3";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

export interface UsageInsert {
  provider: string;
  model: string;
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  source: "agent" | "extension";
  cwd: string | null;
  ts?: number; // defaults to Date.now()
}

export interface UsageRow {
  ts: number;
  provider: string;
  model: string;
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  calls: number;
  source: string;
  cwd: string | null;
}

export interface GroupedRow {
  bucket: string;
  provider: string;
  model: string;
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  calls: number;
}

export interface Totals {
  calls: number;
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
}

export type Breakdown = "day" | "week" | "month";

const SCHEMA = `
CREATE TABLE IF NOT EXISTS usage (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  ts          INTEGER NOT NULL,
  provider    TEXT NOT NULL,
  model       TEXT NOT NULL,
  input       INTEGER NOT NULL,
  output      INTEGER NOT NULL,
  cache_read  INTEGER NOT NULL DEFAULT 0,
  cache_write INTEGER NOT NULL DEFAULT 0,
  calls       INTEGER NOT NULL DEFAULT 1,
  source      TEXT NOT NULL DEFAULT 'agent',
  cwd         TEXT
);
CREATE INDEX IF NOT EXISTS idx_ts ON usage(ts);
CREATE INDEX IF NOT EXISTS idx_provider_model ON usage(provider, model);
`;

function bucketExpr(breakdown: Breakdown): string {
  switch (breakdown) {
    case "day":
      return `strftime('%Y-%m-%d', ts / 1000, 'unixepoch')`;
    case "week":
      return `strftime('%Y-W%W', ts / 1000, 'unixepoch')`;
    case "month":
      return `strftime('%Y-%m', ts / 1000, 'unixepoch')`;
  }
}

export class TokenDb {
  private db: Database.Database;

  constructor(dbPath: string) {
    mkdirSync(dirname(dbPath), { recursive: true });
    this.db = new Database(dbPath);
    this.db.pragma("journal_mode = WAL");
    this.db.exec(SCHEMA);
  }

  insert(row: UsageInsert): void {
    const ts = row.ts ?? Date.now();
    this.db.prepare(`
      INSERT INTO usage (ts, provider, model, input, output, cache_read, cache_write, source, cwd)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(ts, row.provider, row.model, row.input, row.output, row.cacheRead, row.cacheWrite, row.source, row.cwd);
  }

  query(from: Date, to: Date, cwd?: string): UsageRow[] {
    const sql = cwd
      ? `SELECT ts, provider, model, input, output, cache_read as cacheRead, cache_write as cacheWrite, calls, source, cwd FROM usage WHERE ts >= ? AND ts < ? AND cwd = ? ORDER BY ts`
      : `SELECT ts, provider, model, input, output, cache_read as cacheRead, cache_write as cacheWrite, calls, source, cwd FROM usage WHERE ts >= ? AND ts < ? ORDER BY ts`;
    const params = cwd ? [from.getTime(), to.getTime(), cwd] : [from.getTime(), to.getTime()];
    return this.db.prepare(sql).all(...params) as UsageRow[];
  }

  queryGrouped(from: Date, to: Date, breakdown: Breakdown, cwd?: string): GroupedRow[] {
    const bucket = bucketExpr(breakdown);
    const cwdClause = cwd ? " AND cwd = ?" : "";
    const params = cwd
      ? [from.getTime(), to.getTime(), cwd]
      : [from.getTime(), to.getTime()];

    const sql = `
      SELECT
        ${bucket} AS bucket,
        provider,
        model,
        SUM(input) as input,
        SUM(output) as output,
        SUM(cache_read) as cacheRead,
        SUM(cache_write) as cacheWrite,
        SUM(calls) as calls
      FROM usage
      WHERE ts >= ? AND ts < ?${cwdClause}
      GROUP BY bucket, provider, model
      ORDER BY bucket ASC, provider ASC, model ASC
    `;
    return this.db.prepare(sql).all(...params) as GroupedRow[];
  }

  totals(from: Date, to: Date, cwd?: string): Totals {
    const cwdClause = cwd ? " AND cwd = ?" : "";
    const params = cwd
      ? [from.getTime(), to.getTime(), cwd]
      : [from.getTime(), to.getTime()];

    const sql = `
      SELECT
        COALESCE(SUM(calls), 0) as calls,
        COALESCE(SUM(input), 0) as input,
        COALESCE(SUM(output), 0) as output,
        COALESCE(SUM(cache_read), 0) as cacheRead,
        COALESCE(SUM(cache_write), 0) as cacheWrite
      FROM usage
      WHERE ts >= ? AND ts < ?${cwdClause}
    `;
    return this.db.prepare(sql).get(...params) as Totals;
  }

  close(): void {
    this.db.close();
  }
}

import { truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";

import type { GroupedRow, Totals, Breakdown } from "./db.js";
export type RenderRow = GroupedRow;
export type RenderTotals = Totals;
export type BreakdownOption = Breakdown;

export type RangeOption = "week" | "month" | "year";

const RANGES: RangeOption[] = ["week", "month", "year"];
const BREAKDOWN_BY_RANGE: Record<RangeOption, BreakdownOption[]> = {
  week: ["day"],
  month: ["day", "week"],
  year: ["week", "month"],
};

export function getBreakdownsForRange(range: RangeOption): BreakdownOption[] {
  return BREAKDOWN_BY_RANGE[range];
}

export function nextRange(current: RangeOption): RangeOption {
  const idx = RANGES.indexOf(current);
  return RANGES[(idx + 1) % RANGES.length];
}

export function nextBreakdown(range: RangeOption, current: BreakdownOption): BreakdownOption {
  const options = BREAKDOWN_BY_RANGE[range];
  const idx = options.indexOf(current);
  return options[(idx + 1) % options.length];
}

export function formatNumber(n: number): string {
  if (n < 1_000) return String(n);
  if (n < 999_500) return (n / 1_000).toFixed(1) + "K";
  return (n / 1_000_000).toFixed(1) + "M";
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function formatBucket(bucket: string, breakdown: BreakdownOption): string {
  if (breakdown === "day") {
    const [y, m, d] = bucket.split("-");
    return `${MONTHS[parseInt(m!, 10) - 1]} ${d}`;
  }
  if (breakdown === "week") {
    const idx = bucket.indexOf("-W");
    return idx >= 0 ? bucket.slice(idx + 1) : bucket;
  }
  const [y, m] = bucket.split("-");
  return `${MONTHS[parseInt(m!, 10) - 1]} ${y}`;
}

export function rangeLabel(range: RangeOption): string {
  switch (range) {
    case "week": return "1 week";
    case "month": return "1 month";
    case "year": return "1 year";
  }
}

export function rangeStartDate(range: RangeOption): Date {
  const now = new Date();
  const d = new Date(now);
  if (range === "week") d.setDate(d.getDate() - 7);
  else if (range === "month") d.setMonth(d.getMonth() - 1);
  else d.setFullYear(d.getFullYear() - 1);
  return d;
}

export function renderHeader(theme: any, startDate: Date, range: RangeOption): string {
  const dateStr = startDate.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  return theme.bold(theme.fg("accent", `Token Usage — since ${dateStr} (${rangeLabel(range)})`));
}

export function renderTable(
  rows: RenderRow[],
  totals: RenderTotals,
  breakdown: BreakdownOption,
  theme: any,
  width: number,
): string[] {
  const lines: string[] = [];

  const colDate = 10;
  const colModel = 28;
  const colNum = 8;
  const sep = "  ";

  const headerCols = [
    "Date".padEnd(colDate),
    "Model".padEnd(colModel),
    "Calls".padStart(colNum),
    "Input".padStart(colNum),
    "Output".padStart(colNum),
    "CacheR".padStart(colNum),
    "CacheW".padStart(colNum),
    "Total".padStart(colNum),
  ];
  const headerLine = headerCols.join(sep);
  lines.push(theme.fg("dim", "─".repeat(width)));
  lines.push(theme.fg("dim", truncateToWidth(headerLine, width)));
  lines.push(theme.fg("dim", "─".repeat(width)));

  let lastBucket = "";
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const dateLabel = row.bucket === lastBucket ? "" : formatBucket(row.bucket, breakdown);
    lastBucket = row.bucket;

    const modelLabel = `${row.provider}/${row.model}`;
    const total = row.input + row.output + row.cacheRead + row.cacheWrite;
    const line = [
      dateLabel.padEnd(colDate),
      truncateToWidth(modelLabel, colModel).padEnd(colModel),
      String(row.calls).padStart(colNum),
      formatNumber(row.input).padStart(colNum),
      formatNumber(row.output).padStart(colNum),
      formatNumber(row.cacheRead).padStart(colNum),
      formatNumber(row.cacheWrite).padStart(colNum),
      formatNumber(total).padStart(colNum),
    ].join(sep);

    lines.push(truncateToWidth(line, width));
    if (i < rows.length - 1 && rows[i + 1]?.bucket !== row.bucket) {
      lines.push(theme.fg("dim", "·".repeat(Math.min(width, 60))));
    }
  }

  lines.push(theme.fg("dim", "─".repeat(width)));
  const grandTotal = totals.input + totals.output + totals.cacheRead + totals.cacheWrite;
  const totalLine = [
    "Totals".padEnd(colDate),
    "".padEnd(colModel),
    String(totals.calls).padStart(colNum),
    formatNumber(totals.input).padStart(colNum),
    formatNumber(totals.output).padStart(colNum),
    formatNumber(totals.cacheRead).padStart(colNum),
    formatNumber(totals.cacheWrite).padStart(colNum),
    formatNumber(grandTotal).padStart(colNum),
  ].join(sep);
  lines.push(theme.bold(truncateToWidth(totalLine, width)));

  return lines;
}

export function renderFooter(
  theme: any,
  range: RangeOption,
  breakdown: BreakdownOption,
  canTab: boolean,
): string {
  const rangePart = `Ctrl+R: ${rangeLabel(range)}`;
  const tabPart = canTab ? `Tab: breakdown: ${breakdown}` : theme.fg("dim", `breakdown: ${breakdown}`);
  const escPart = "Esc to close";
  return theme.fg("dim", `${rangePart}    ${tabPart}    ${escPart}`);
}

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { TokenDb, type UsageRow } from "./db.js";
import { mkdirSync, rmSync } from "node:fs";
import { join } from "node:path";

const TEST_DIR = join(process.cwd(), ".test-db");

let db: TokenDb;

beforeEach(() => {
  mkdirSync(TEST_DIR, { recursive: true });
  db = new TokenDb(join(TEST_DIR, "test.db"));
});

afterEach(() => {
  db.close();
  rmSync(TEST_DIR, { recursive: true, force: true });
});

describe("TokenDb", () => {
  it("inserts and queries a row", () => {
    db.insert({
      provider: "anthropic",
      model: "claude-sonnet-4-20250514",
      input: 1000,
      output: 500,
      cacheRead: 200,
      cacheWrite: 50,
      source: "agent",
      cwd: "/home/user/project",
    });

    const rows = db.query(new Date("2020-01-01"), new Date("2030-01-01"));
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      provider: "anthropic",
      model: "claude-sonnet-4-20250514",
      input: 1000,
      output: 500,
      cacheRead: 200,
      cacheWrite: 50,
      source: "agent",
    });
  });

  it("groups by day", () => {
    const day1 = new Date("2026-04-21T10:00:00Z").getTime();
    const day2 = new Date("2026-04-22T10:00:00Z").getTime();

    db.insert({ provider: "anthropic", model: "sonnet", input: 100, output: 50, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: day1 });
    db.insert({ provider: "anthropic", model: "sonnet", input: 200, output: 50, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: day1 });
    db.insert({ provider: "anthropic", model: "sonnet", input: 300, output: 150, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: day2 });

    const groups = db.queryGrouped(
      new Date("2026-04-21"), new Date("2026-04-23"), "day",
    );

    // same model on same day merges into 1 row per group
    expect(groups).toHaveLength(2);
    expect(groups[0].bucket).toBe("2026-04-21");
    expect(groups[0].provider).toBe("anthropic");
    expect(groups[0].input).toBe(300);
    expect(groups[0].output).toBe(100);
    expect(groups[1].bucket).toBe("2026-04-22");
    expect(groups[1].input).toBe(300);
    expect(groups[1].output).toBe(150);
  });

  it("groups by week", () => {
    // Apr 19 (Sun) and Apr 20 (Mon) are in different weeks
    const sun = new Date("2026-04-19T12:00:00Z").getTime();
    const mon = new Date("2026-04-20T12:00:00Z").getTime();

    db.insert({ provider: "anthropic", model: "sonnet", input: 100, output: 50, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: sun });
    db.insert({ provider: "anthropic", model: "sonnet", input: 200, output: 100, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: mon });

    const groups = db.queryGrouped(
      new Date("2026-04-19"), new Date("2026-04-21"), "week",
    );

    expect(groups).toHaveLength(2); // two different weeks
  });

  it("groups by month", () => {
    const mar = new Date("2026-03-15T12:00:00Z").getTime();
    const apr = new Date("2026-04-15T12:00:00Z").getTime();

    db.insert({ provider: "anthropic", model: "sonnet", input: 100, output: 50, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: mar });
    db.insert({ provider: "anthropic", model: "sonnet", input: 200, output: 100, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: null, ts: apr });

    const groups = db.queryGrouped(
      new Date("2026-03-01"), new Date("2026-05-01"), "month",
    );

    expect(groups).toHaveLength(2);
    expect(groups[0].bucket).toBe("2026-03");
    expect(groups[1].bucket).toBe("2026-04");
  });

  it("returns totals for a range", () => {
    const ts = new Date("2026-04-21T10:00:00Z").getTime();
    db.insert({ provider: "anthropic", model: "sonnet", input: 1000, output: 500, cacheRead: 200, cacheWrite: 50, source: "agent", cwd: null, ts });
    db.insert({ provider: "openai", model: "gpt-4o", input: 500, output: 200, cacheRead: 0, cacheWrite: 0, source: "extension", cwd: null, ts });

    const totals = db.totals(new Date("2026-04-01"), new Date("2026-05-01"));
    expect(totals).toEqual({
      calls: 2,
      input: 1500,
      output: 700,
      cacheRead: 200,
      cacheWrite: 50,
    });
  });

  it("filters by cwd when provided", () => {
    const ts = new Date("2026-04-21T10:00:00Z").getTime();
    db.insert({ provider: "anthropic", model: "sonnet", input: 100, output: 50, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: "/project/a", ts });
    db.insert({ provider: "anthropic", model: "sonnet", input: 200, output: 100, cacheRead: 0, cacheWrite: 0, source: "agent", cwd: "/project/b", ts });

    const rows = db.query(new Date("2020-01-01"), new Date("2030-01-01"), "/project/a");
    expect(rows).toHaveLength(1);
    expect(rows[0].input).toBe(100);
  });

  it("handles empty query results", () => {
    const from = new Date("2026-01-01");
    const to = new Date("2026-01-02");

    const rows = db.query(from, to);
    expect(rows).toEqual([]);

    const groups = db.queryGrouped(from, to, "day");
    expect(groups).toEqual([]);

    const totals = db.totals(from, to);
    expect(totals).toEqual({
      calls: 0,
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0,
    });
  });
});

import { describe, it, expect } from "vitest";
import { formatNumber, formatBucket, type RangeOption, type BreakdownOption } from "./render.js";

describe("formatNumber", () => {
  it("formats numbers under 1000 as-is", () => {
    expect(formatNumber(42)).toBe("42");
    expect(formatNumber(999)).toBe("999");
  });

  it("formats thousands with K suffix", () => {
    expect(formatNumber(1_000)).toBe("1.0K");
    expect(formatNumber(1_500)).toBe("1.5K");
    expect(formatNumber(999_999)).toBe("1.0M");
  });

  it("formats millions with M suffix", () => {
    expect(formatNumber(1_000_000)).toBe("1.0M");
    expect(formatNumber(1_500_000)).toBe("1.5M");
    expect(formatNumber(1_570_000)).toBe("1.6M");
  });
});

describe("formatBucket", () => {
  it("formats day buckets", () => {
    expect(formatBucket("2026-04-21", "day")).toBe("Apr 21");
    expect(formatBucket("2026-01-05", "day")).toBe("Jan 05");
  });

  it("formats week buckets", () => {
    expect(formatBucket("2026-W16", "week")).toBe("W16");
    expect(formatBucket("2026-W01", "week")).toBe("W01");
  });

  it("formats month buckets", () => {
    expect(formatBucket("2026-04", "month")).toBe("Apr 2026");
    expect(formatBucket("2026-01", "month")).toBe("Jan 2026");
  });
});

