		"@types/node": "^22.0.0",
		"typescript": "^5.8.0",
		"vitest": "^3.0.0"
	},
	"scripts": {
		"typecheck": "tsc --noEmit",
		"test": "vitest run"
	}
}

import { DatabaseSync } from "node:sqlite";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

export interface UsageInsert {
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	source: "agent" | "extension";
	cwd: string | null;
	ts?: number; // defaults to Date.now()
}

export interface UsageRow {
	ts: number;
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	calls: number;
	source: string;
	cwd: string | null;
}

export interface GroupedRow {
	bucket: string;
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	calls: number;
}

export interface Totals {
	calls: number;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
}

export type Breakdown = "day" | "week" | "month";

const SCHEMA = `
CREATE TABLE IF NOT EXISTS usage (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  ts          INTEGER NOT NULL,
  provider    TEXT NOT NULL,
  model       TEXT NOT NULL,
  input       INTEGER NOT NULL,
  output      INTEGER NOT NULL,
  cache_read  INTEGER NOT NULL DEFAULT 0,
  cache_write INTEGER NOT NULL DEFAULT 0,
  calls       INTEGER NOT NULL DEFAULT 1,
  source      TEXT NOT NULL DEFAULT 'agent',
  cwd         TEXT
);
CREATE INDEX IF NOT EXISTS idx_ts ON usage(ts);
CREATE INDEX IF NOT EXISTS idx_provider_model ON usage(provider, model);
`;

function bucketExpr(breakdown: Breakdown): string {
	switch (breakdown) {
		case "day":
			// strftime on unixepoch seconds in UTC. Buckets in UTC so the
			// grouping is deterministic across timezone changes.
			return `strftime('%Y-%m-%d', ts / 1000, 'unixepoch')`;
		case "week":
			return `strftime('%Y-W%W', ts / 1000, 'unixepoch')`;
		case "month":
			return `strftime('%Y-%m', ts / 1000, 'unixepoch')`;
	}
}

function rowsFrom<T>(result: unknown): T[] {
	// node:sqlite returns an array of plain objects whose property names
	// match the SELECT aliases (case-sensitive).
	if (!Array.isArray(result)) return [];
	return result as T[];
}

function rowFrom<T>(result: unknown): T {
	if (!result || typeof result !== "object") {
		throw new Error("Expected single row from query");
	}
	return result as T;
}

export class TokenDb {
	private db: DatabaseSync;

	constructor(dbPath: string) {
		mkdirSync(dirname(dbPath), { recursive: true });
		this.db = new DatabaseSync(dbPath);
		// WAL is supported on node:sqlite via the journal_mode pragma.
		this.db.exec("PRAGMA journal_mode = WAL");
		this.db.exec(SCHEMA);
	}

	insert(row: UsageInsert): void {
		const ts = row.ts ?? Date.now();
		this.db
			.prepare(
				`INSERT INTO usage (ts, provider, model, input, output, cache_read, cache_write, source, cwd)
				 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			)
			.run(
				ts,
				row.provider,
				row.model,
				row.input,
				row.output,
				row.cacheRead,
				row.cacheWrite,
				row.source,
				row.cwd,
			);
	}

	query(from: Date, to: Date, cwd?: string): UsageRow[] {
		const sql = cwd
			? `SELECT ts, provider, model, input, output, cache_read AS cacheRead, cache_write AS cacheWrite, calls, source, cwd
			   FROM usage
			   WHERE ts >= ? AND ts < ? AND cwd = ?
			   ORDER BY ts`
			: `SELECT ts, provider, model, input, output, cache_read AS cacheRead, cache_write AS cacheWrite, calls, source, cwd
			   FROM usage
			   WHERE ts >= ? AND ts < ?
			   ORDER BY ts`;
		const params = cwd ? [from.getTime(), to.getTime(), cwd] : [from.getTime(), to.getTime()];
		return rowsFrom<UsageRow>(this.db.prepare(sql).all(...params));
	}

	queryGrouped(from: Date, to: Date, breakdown: Breakdown, cwd?: string): GroupedRow[] {
		const bucket = bucketExpr(breakdown);
		const cwdClause = cwd ? " AND cwd = ?" : "";
		const params: (number | string)[] = cwd
			? [from.getTime(), to.getTime(), cwd]
			: [from.getTime(), to.getTime()];

		const sql = `
			SELECT
				${bucket} AS bucket,
				provider,
				model,
				SUM(input) AS input,
				SUM(output) AS output,
				SUM(cache_read) AS cacheRead,
				SUM(cache_write) AS cacheWrite,
				SUM(calls) AS calls
			FROM usage
			WHERE ts >= ? AND ts < ?${cwdClause}
			GROUP BY bucket, provider, model
			ORDER BY bucket ASC, provider ASC, model ASC
		`;
		return rowsFrom<GroupedRow>(this.db.prepare(sql).all(...params));
	}

	totals(from: Date, to: Date, cwd?: string): Totals {
		const cwdClause = cwd ? " AND cwd = ?" : "";
		const params: (number | string)[] = cwd
			? [from.getTime(), to.getTime(), cwd]
			: [from.getTime(), to.getTime()];

		const sql = `
			SELECT
				COALESCE(SUM(calls), 0) AS calls,
				COALESCE(SUM(input), 0) AS input,
				COALESCE(SUM(output), 0) AS output,
				COALESCE(SUM(cache_read), 0) AS cacheRead,
				COALESCE(SUM(cache_write), 0) AS cacheWrite
			FROM usage
			WHERE ts >= ? AND ts < ?${cwdClause}
		`;
		const result = this.db.prepare(sql).get(...params);
		return rowFrom<Totals>(result);
	}

	close(): void {
		this.db.close();
	}
}

import { truncateToWidth } from "@earendil-works/pi-tui";

import type { GroupedRow, Totals, Breakdown } from "./db.js";
export type RenderRow = GroupedRow;
export type RenderTotals = Totals;
export type BreakdownOption = Breakdown;

export type RangeOption = "week" | "month" | "year";

const RANGES: RangeOption[] = ["week", "month", "year"];
const BREAKDOWN_BY_RANGE: Record<RangeOption, BreakdownOption[]> = {
	week: ["day"],
	month: ["day", "week"],
	year: ["week", "month"],
};

export function getBreakdownsForRange(range: RangeOption): BreakdownOption[] {
	return BREAKDOWN_BY_RANGE[range];
}

export function nextRange(current: RangeOption): RangeOption {
	const idx = RANGES.indexOf(current);
	return RANGES[(idx + 1) % RANGES.length];
}

export function nextBreakdown(range: RangeOption, current: BreakdownOption): BreakdownOption {
	const options = BREAKDOWN_BY_RANGE[range];
	const idx = options.indexOf(current);
	return options[(idx + 1) % options.length];
}

export function formatNumber(n: number): string {
	if (n < 1_000) return String(n);
	if (n < 999_500) return (n / 1_000).toFixed(1) + "K";
	return (n / 1_000_000).toFixed(1) + "M";
}

const MONTHS = [
	"Jan", "Feb", "Mar", "Apr", "May", "Jun",
	"Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

export function formatBucket(bucket: string, breakdown: BreakdownOption): string {
	if (breakdown === "day") {
		const [y, m, d] = bucket.split("-");
		return `${MONTHS[parseInt(m!, 10) - 1]} ${d}`;
	}
	if (breakdown === "week") {
		const idx = bucket.indexOf("-W");
		return idx >= 0 ? bucket.slice(idx + 1) : bucket;
	}
	const [y, m] = bucket.split("-");
	return `${MONTHS[parseInt(m!, 10) - 1]} ${y}`;
}

export function rangeLabel(range: RangeOption): string {
	switch (range) {
		case "week":
			return "1 week";
		case "month":
			return "1 month";
		case "year":
			return "1 year";
	}
}

export function rangeStartDate(range: RangeOption): Date {
	const now = new Date();
	const d = new Date(now);
	if (range === "week") d.setDate(d.getDate() - 7);
	else if (range === "month") d.setMonth(d.getMonth() - 1);
	else d.setFullYear(d.getFullYear() - 1);
	return d;
}

export function renderHeader(theme: any, startDate: Date, range: RangeOption): string {
	const dateStr = startDate.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
		year: "numeric",
	});
	return theme.bold(theme.fg("accent", `Token Usage — since ${dateStr} (${rangeLabel(range)})`));
}

export function renderTable(
	rows: RenderRow[],
	totals: RenderTotals,
	breakdown: BreakdownOption,
	theme: any,
	width: number,
): string[] {
	const lines: string[] = [];

	const colDate = 10;
	const colModel = 28;
	const colNum = 8;
	const sep = "  ";

	const headerCols = [
		"Date".padEnd(colDate),
		"Model".padEnd(colModel),
		"Calls".padStart(colNum),
		"Input".padStart(colNum),
		"Output".padStart(colNum),
		"CacheR".padStart(colNum),
		"CacheW".padStart(colNum),
		"Total".padStart(colNum),
	];
	const headerLine = headerCols.join(sep);
	lines.push(theme.fg("dim", "─".repeat(width)));
	lines.push(theme.fg("dim", truncateToWidth(headerLine, width)));
	lines.push(theme.fg("dim", "─".repeat(width)));

	let lastBucket = "";
	for (let i = 0; i < rows.length; i++) {
		const row = rows[i]!;
		const dateLabel = row.bucket === lastBucket ? "" : formatBucket(row.bucket, breakdown);
		lastBucket = row.bucket;

		const modelLabel = `${row.provider}/${row.model}`;
		const total = row.input + row.output + row.cacheRead + row.cacheWrite;
		const line = [
			dateLabel.padEnd(colDate),
			truncateToWidth(modelLabel, colModel).padEnd(colModel),
			String(row.calls).padStart(colNum),
			formatNumber(row.input).padStart(colNum),
			formatNumber(row.output).padStart(colNum),
			formatNumber(row.cacheRead).padStart(colNum),
			formatNumber(row.cacheWrite).padStart(colNum),
			formatNumber(total).padStart(colNum),
		].join(sep);

		lines.push(truncateToWidth(line, width));
		if (i < rows.length - 1 && rows[i + 1]?.bucket !== row.bucket) {
			lines.push(theme.fg("dim", "·".repeat(Math.min(width, 60))));
		}
	}

	lines.push(theme.fg("dim", "─".repeat(width)));
	const grandTotal = totals.input + totals.output + totals.cacheRead + totals.cacheWrite;
	const totalLine = [
		"Totals".padEnd(colDate),
		"".padEnd(colModel),
		String(totals.calls).padStart(colNum),
		formatNumber(totals.input).padStart(colNum),
		formatNumber(totals.output).padStart(colNum),
		formatNumber(totals.cacheRead).padStart(colNum),
		formatNumber(totals.cacheWrite).padStart(colNum),
		formatNumber(grandTotal).padStart(colNum),
	].join(sep);
	lines.push(theme.bold(truncateToWidth(totalLine, width)));

	return lines;
}

export function renderFooter(
	theme: any,
	range: RangeOption,
	breakdown: BreakdownOption,
	canTab: boolean,
): string {
	const rangePart = `Ctrl+R: ${rangeLabel(range)}`;
	const tabPart = canTab
		? `Tab: breakdown: ${breakdown}`
		: theme.fg("dim", `breakdown: ${breakdown}`);
	const escPart = "Esc to close";
	return theme.fg("dim", `${rangePart}    ${tabPart}    ${escPart}`);
}

