// Smoke test: load the extension via jiti (the same loader pi uses) and
// ensure the default export factory can be invoked without errors.
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true });
const mod = await jiti.import("./src/index.ts") as { default: (pi: any) => void };

// Minimal pi stub. We only need to record the registered handlers and
// verify the factory wires them up.
const handlers: Record<string, Array<(event: any, ctx: any) => unknown>> = {};
const eventBusHandlers: Record<string, Array<(data: unknown) => void>> = {};

const pi = {
	on(event: string, handler: (event: any, ctx: any) => unknown) {
		(handlers[event] ??= []).push(handler);
	},
	registerCommand(name: string, _opts: unknown) {
		// smoke test: just check the command name is correct
		if (name !== "token-usage") {
			throw new Error(`Unexpected command name: ${name}`);
		}
	},
	events: {
		on(channel: string, handler: (data: unknown) => void) {
			(eventBusHandlers[channel] ??= []).push(handler);
			return () => {};
		},
	},
};

mod.default(pi);

// 1. message_end handler registered
if (!handlers.message_end || handlers.message_end.length !== 1) {
	throw new Error("message_end handler not registered");
}

// 2. session_shutdown handler registered
if (!handlers.session_shutdown || handlers.session_shutdown.length !== 1) {
	throw new Error("session_shutdown handler not registered");
}

// 3. /token-usage command registered
console.log("registered commands ok");

// 4. model:usage event handler registered
if (!eventBusHandlers["model:usage"] || eventBusHandlers["model:usage"].length !== 1) {
	throw new Error("model:usage event handler not registered");
}

console.log("smoke: extension factory wired all required handlers");

